//! House scoring: feng shui luck (`m_huusui_room.c`,
//! `m_huusui_room_ovl.c`) and the Happy Room Academy (`m_mark_room.c`,
//! `m_mark_room_ovl.c`).
//!
//! Source-verified against ac-decomp (primary) and ACGC-PC-Port
//! (identical). Data tables in `room_scoring_tables.rs` are generated by
//! `tools/gen_room_scoring_tables.py`, which compiles the C initializers
//! with mingw32 gcc so every enum resolves exactly.
//!
//! Furniture footprints come from `aMR_GetFurnitureUnit(item)` (size
//! 0 = 1x1, 1 = 1x2, 2 = 2x2), passed in by the caller.
//!
//! ## Feng shui (`mHsRm_HuusuiRoomOvl`, run for the active player unless
//! on the part-time job or a visitor)
//! Room bands: units `<= start` are north/west, `>= max - start - 1` are
//! south/east (`start` = 1 for a 1x1 in the 6-unit room, else 2). A piece
//! scores only if **all** its units are in one band:
//! - yellow: money +4 on the west side;
//! - red: goods +8 on the east side;
//! - orange: money +2 / goods +4 on the north side;
//! - green: money +2 / goods +4 on the south side;
//! - lucky items: money +4 / goods +8 anywhere (always).
//!
//! Pieces with a "face" lose money 10 / goods 5 when they are in a band
//! and their front faces the adjacent wall (the wall-touching units must
//! be 2 for multi-unit pieces). Main floor (6/8/10 units), upstairs (8)
//! and basement (10) are summed. Goods power is capped at 40 then halved,
//! rounding up. Results go to `money_power` / `goods_power`.
//!
//! ## Happy Room Academy (daily letter)
//! Scheduling (`mMkRm_MarkRoom`): non-members get the welcome letter
//! (handbill 0x1EF) and become members. Members are scored once per day
//! when the house changed (`house_updated`); otherwise a 2-in-10 chance
//! (RANDOM(10) is 5 or 9) sends one of 19 hint letters (0x1DC + i), cycling
//! through unused hints. Leaving your room with changes sets the flag.
//!
//! Scoring (`mMkRm_MarkRoomOneFloor`, interior units 1..max-1 of both
//! layers; main floor full evaluation, upstairs a reduced set):
//! - base points: each furniture's acquisition type (`birth_type`) value
//!   (e.g. shop group 51, events 412, lottery 1029, fossil 300/1000,
//!   NES 1983) + wallpaper and carpet by their source (my-designs 3);
//! - necessities (chair, dresser, wardrobe, table, bed): all five of one
//!   base series +16,000, else all five across series +4,400;
//! - base series (10 items) complete +48,000, plus wall+floor match
//!   +10,000 or one of them +4,800;
//! - theme series complete with its wall and floor: 7,000 per item +
//!   15,000 (wall and floor alone still +10,000); other furniture in a
//!   completed theme room costs 4,000 each;
//! - set series (fruit, dinosaurs, guitars...) complete: 3,000 per item;
//! - lucky furniture +777 each; faced furniture facing a wall -800 each;
//! - clutter (non-furniture items on the floor, or on surfaces) -1 each;
//! - floored at 0. Rewards: 70,000 -> house model 2, 100,000 -> model 4.
//!
//! ## Decomp bugs preserved
//! - `mMkRm_CountCharactor(.., forward = FALSE)` was meant to scan from
//!   the end but walks forward and returns the same as the forward mode.
//! - Theme "almost complete" recommends a **carpet** when the wall is the
//!   one missing and vice versa (wrong item category).
//! - The plesiosaur series name reads "hutaba" (futabasaurus).

use crate::room_scoring_tables::*;
use std::sync::OnceLock;

pub const FTR_NUM: usize = 1266;
pub const UT_X_NUM: usize = 16;

/// `mRmTp_FTRSIZE_*`.
pub const FTRSIZE_1X1: u8 = 0;
pub const FTRSIZE_1X2: u8 = 1;
pub const FTRSIZE_2X2: u8 = 2;

pub const EMPTY_NO: u16 = 0x0000;
pub const RSV_NO: u16 = 0xFFFF;
pub const RSV_WALL_NO: u16 = 0xFFFE;
pub const RSV_DOOR: u16 = 0xFE1B;
pub const RSV_FE1C: u16 = 0xFE1C;
pub const RSV_FE1F: u16 = 0xFE1F;
pub const EXIT_DOOR: u16 = 0x4080;
pub const ITM_DIARY_START: u16 = 0x2B00;
pub const ITM_DIARY_END: u16 = ITM_DIARY_START + 16;
pub const ITM_CARPET_START: u16 = 0x2600;
pub const ITM_WALL_START: u16 = 0x2700;

/// `ITEM_IS_FTR`: name types 1 (FTR0) and 3 (FTR1).
pub fn is_ftr(item: u16) -> bool {
    matches!((item & 0xF000) >> 12, 1 | 3)
}

/// `mRmTp_FtrItemNo2FtrIdx` (0 for non-furniture, like the C).
pub fn ftr_index(item: u16) -> usize {
    match (item & 0xF000) >> 12 {
        1 => ((item - 0x1000) >> 2) as usize,
        3 => 0x400 + ((item - 0x3000) >> 2) as usize,
        _ => 0,
    }
}

/// `mRmTp_FtrIdx2FtrItemNo(idx, SOUTH)`.
pub fn ftr_item_no(idx: usize) -> u16 {
    if idx < 0x400 {
        0x1000 + ((idx as u16) << 2)
    } else {
        0x3000 + (((idx - 0x400) as u16) << 2)
    }
}

/// `mRmTp_GetFurnitureData` unit offsets: (exists, dx, dz).
pub fn unit_offsets(size: u8, rotation: u8) -> [(bool, i32, i32); 4] {
    const N: (bool, i32, i32) = (false, 0, 0);
    match size {
        FTRSIZE_1X2 => match rotation & 3 {
            0 => [(true, 0, 0), (true, 1, 0), N, N],
            1 => [(true, 0, 0), (true, 0, -1), N, N],
            2 => [(true, 0, 0), (true, -1, 0), N, N],
            _ => [(true, 0, 0), (true, 0, 1), N, N],
        },
        FTRSIZE_2X2 => [(true, 0, 0), (true, 1, 0), (true, 1, 1), (true, 0, 1)],
        _ => [(true, 0, 0), N, N, N],
    }
}

fn units_of(item: u16, ut_x: i32, ut_z: i32, size: u8) -> Vec<(i32, i32)> {
    unit_offsets(size, (item & 3) as u8)
        .iter()
        .filter(|u| u.0)
        .map(|&(_, dx, dz)| (ut_x + dx, ut_z + dz))
        .collect()
}

// ---------------------------------------------------------------------------
// Feng shui
// ---------------------------------------------------------------------------

pub const HUUSUI_NONE: u8 = 0;
pub const HUUSUI_YELLOW: u8 = 1;
pub const HUUSUI_RED: u8 = 2;
pub const HUUSUI_ORANGE: u8 = 3;
pub const HUUSUI_GREEN: u8 = 4;
pub const HUUSUI_LUCKY: u8 = 5;

/// `mHsRm_DIRECTION_*` bit positions.
const DIR_SOUTH: usize = 0;
const DIR_EAST: usize = 1;
const DIR_NORTH: usize = 2;
const DIR_WEST: usize = 3;

/// (wall bits, points) per feng shui colour.
const MONEY_POWER: [(u8, i32); 6] = [(0, 0), (1 << DIR_WEST, 4), (0, 0), (1 << DIR_NORTH, 2), (1 << DIR_SOUTH, 2), (0xF, 4)];
const GOODS_POWER: [(u8, i32); 6] = [(0, 0), (0, 0), (1 << DIR_EAST, 8), (1 << DIR_NORTH, 4), (1 << DIR_SOUTH, 4), (0xF, 8)];

pub const GOODS_POWER_MAX: i32 = 40;
pub const UNIT_MAX_MAIN: [i32; 4] = [6, 8, 10, 10];
pub const UNIT_MAX_UPPER: i32 = 8;
pub const UNIT_MAX_BASEMENT: i32 = 10;

/// `mHsRm_EvaluateHuusuiPoint_Single`: (money, goods).
pub fn huusui_single(item: u16, ut_x: i32, ut_z: i32, ut_max: i32, size: u8) -> (i32, i32) {
    let info = HUUSUI_FTR_INFO[ftr_index(item).min(FTR_NUM - 1)];
    let kind = info & 0xF;
    let has_face = info >> 4 != 0;
    let rot = (item & 3) as usize;
    let units = units_of(item, ut_x, ut_z, size);
    let ut_value = units.len() as i32;
    let start = if ut_max == 6 && ut_value == 1 { 1 } else { 2 };

    let mut side = [0i32; 4];
    let mut wall = [0i32; 4];
    for &(x, z) in &units {
        if z <= start {
            side[DIR_NORTH] += 1;
            if z <= 1 {
                wall[DIR_NORTH] += 1;
            }
        } else if z >= ut_max - start - 1 {
            side[DIR_SOUTH] += 1;
            if z >= ut_max - 2 {
                wall[DIR_SOUTH] += 1;
            }
        }
        if x <= start {
            side[DIR_WEST] += 1;
            if x <= 1 {
                wall[DIR_WEST] += 1;
            }
        } else if x >= ut_max - start - 1 {
            side[DIR_EAST] += 1;
            if x >= ut_max - 2 {
                wall[DIR_EAST] += 1;
            }
        }
    }
    let mut side_bits = 0u8;
    let mut wall_bits = 0u8;
    for i in 0..4 {
        if side[i] == ut_value {
            side_bits |= 1 << i;
        }
        if (ut_value >= 2 && wall[i] >= 2) || (ut_value == 1 && wall[i] >= 1) {
            wall_bits |= 1 << i;
        }
    }
    let (mut money, mut goods) = (0, 0);
    if kind == HUUSUI_LUCKY {
        money += 4;
        goods += 8;
    }
    if side_bits != 0 {
        if kind != HUUSUI_LUCKY {
            for i in 0..4 {
                if side_bits & (1 << i) != 0 {
                    let k = kind as usize;
                    if MONEY_POWER[k].0 & (1 << i) != 0 {
                        money += MONEY_POWER[k].1;
                    }
                    if GOODS_POWER[k].0 & (1 << i) != 0 {
                        goods += GOODS_POWER[k].1;
                    }
                }
            }
        }
        if has_face {
            for i in 0..4 {
                if wall_bits & (1 << i) != 0 && rot == i {
                    money -= 10;
                    goods -= 5;
                }
            }
        }
    }
    (money, goods)
}

/// `mHsRm_EvaluateHuusuiPoint` over both layers of one floor.
pub fn huusui_floor(layers: [&[u16; 256]; 2], ut_max: i32, size_of: &impl Fn(u16) -> u8) -> (i32, i32) {
    let (mut money, mut goods) = (0, 0);
    for layer in layers {
        for z in 0..ut_max {
            for x in 0..ut_max {
                let item = layer[(z as usize) * UT_X_NUM + x as usize];
                if is_ftr(item) {
                    let (m, g) = huusui_single(item, x, z, ut_max, size_of(item));
                    money += m;
                    goods += g;
                }
            }
        }
    }
    (money, goods)
}

/// Final goods power: capped at 40, halved, rounded up.
pub fn finish_goods_power(goods: i32) -> i32 {
    let g = goods.min(GOODS_POWER_MAX);
    let half = g as f32 * 0.5;
    let mut out = half as i32;
    if half - out as f32 > 0.0 {
        out += 1;
    }
    out
}

