/// Unpacked `mMkRm_ftr_info_c`.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct HraFtr {
    pub series: usize,
    pub group_idx: u16,
    pub has_face: bool,
    pub is_lucky: bool,
    pub birth_type: usize,
    pub surface_type: u8,
}

fn unpack(v: u32) -> HraFtr {
    HraFtr {
        series: (v & 63) as usize,
        group_idx: ((v >> 6) & 1023) as u16,
        has_face: (v >> 16) & 1 != 0,
        is_lucky: (v >> 17) & 1 != 0,
        birth_type: ((v >> 18) & 63) as usize,
        surface_type: ((v >> 24) & 3) as u8,
    }
}

/// HRA furniture data after `mMkRm_AssignIdxInGroup` (group indices and
/// series sizes), computed once.
pub struct HraData {
    pub ftr: Vec<HraFtr>,
    pub series_num_ftr: [u32; SERIES_NUM],
}

/// `mMkRm_AssignIdxInGroup` applied to the static table.
pub fn hra_data() -> &'static HraData {
    static DATA: OnceLock<HraData> = OnceLock::new();
    DATA.get_or_init(|| {
        let mut ftr: Vec<HraFtr> = MKRM_FTR_INFO.iter().map(|&v| unpack(v)).collect();
        let mut num = [0u32; SERIES_NUM];
        for s in 0..SERIES_NUM {
            let ty = MKRM_SERIES_INFO[s].0;
            let mut group = if ty == SERIES_TYPE_BASE { NOT_NECESSITY } else { 0 };
            let mut count = 0;
            for f in ftr.iter_mut().filter(|f| f.series == s) {
                if ty == SERIES_TYPE_BASE {
                    if f.group_idx >= NOT_NECESSITY {
                        f.group_idx = group;
                        group += 1;
                    }
                } else {
                    f.group_idx = group;
                    group += 1;
                }
                count += 1;
            }
            num[s] = count;
        }
        HraData { ftr, series_num_ftr: num }
    })
}

/// Result of scoring one floor.
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
pub struct HraFloor {
    pub points: i32,
    pub letter_bits: u64,
    pub base_recommendation: u16,
    pub theme_recommendation: u16,
    /// Completed (or almost) theme series name index, if any was set.
    pub series_name: Option<usize>,
}

/// `mRmTp_MakeFtrNoTable`: which furniture covers each unit (edge writes
/// outside the 16x16 grid are dropped; C would write out of bounds).
pub fn make_ftr_no_table(layer: &[u16; 256], size_of: &impl Fn(u16) -> u8) -> [u16; 256] {
    let mut out = [EMPTY_NO; 256];
    for z in 0..16i32 {
        for x in 0..16i32 {
            let item = layer[(z * 16 + x) as usize];
            if is_ftr(item) {
                for (ux, uz) in units_of(item, x, z, size_of(item)) {
                    if (0..16).contains(&ux) && (0..16).contains(&uz) {
                        out[(uz * 16 + ux) as usize] = item;
                    }
                }
            }
        }
    }
    out
}

/// `mMkRm_CheckEdgeZone`.
pub fn check_edge_zone(ut_x: i32, ut_z: i32, direction: u8, room_size: usize) -> bool {
    let far = match room_size {
        0 => 4,
        1 => 6,
        2 | 3 => 8,
        _ => -1,
    };
    match direction {
        0 => ut_z == far,
        1 => ut_x == far,
        2 => ut_z == 1,
        3 => ut_x == 1,
        _ => false,
    }
}

fn is_clutter(item: u16) -> bool {
    !is_ftr(item) && ![RSV_NO, EMPTY_NO, RSV_WALL_NO, RSV_DOOR, EXIT_DOOR, RSV_FE1F, RSV_FE1C].contains(&item)
}

/// `mMkRm_MarkRoomOneFloor`.
pub fn mark_room_one_floor(
    layers: [&[u16; 256]; 2],
    room_size: usize,
    wall_num: usize,
    floor_num: usize,
    mode: u32,
    size_of: &impl Fn(u16) -> u8,
) -> HraFloor {
    let d = hra_data();
    let ut_max = HRA_UNIT_MAX[room_size.min(3)];
    let ftr_table1 = make_ftr_no_table(layers[0], size_of);
    let mut r = HraFloor::default();
    let mut points = 0i32;
    let info = |item: u16| d.ftr[ftr_index(item).min(FTR_NUM - 1)];
    let interior = |f: &mut dyn FnMut(usize, i32, i32, u16)| {
        for (li, layer) in layers.iter().enumerate() {
            for z in 1..ut_max {
                for x in 1..ut_max {
                    f(li, x, z, layer[(z as usize) * UT_X_NUM + x as usize]);
                }
            }
        }
    };

    // mMkRm_MakeFtrTable
    let mut search = [0u32; SERIES_NUM];
    interior(&mut |_, _, _, item| {
        if is_ftr(item) {
            let f = info(item);
            if f.series != SERIES_OTHER {
                search[f.series] |= 1u32.checked_shl(f.group_idx as u32).unwrap_or(0);
            }
        }
    });
    let perfect = |n: u32| if n >= 32 { u32::MAX } else { (1u32 << n) - 1 };
    let series_type = |s: usize| MKRM_SERIES_INFO[s].0;
    let series_wf = |s: usize| MKRM_SERIES_INFO[s].1 as usize;

    if mode & EVAL_BASE_POINT != 0 {
        let mut occur = [0i32; 38];
        interior(&mut |_, _, _, item| {
            if is_ftr(item) {
                occur[info(item).birth_type.min(37)] += 1;
            }
        });
        let mut base = occur.iter().zip(BIRTH_POINTS).map(|(o, p)| o * p).sum::<i32>();
        let fl = floor_num as u8;
        base += if (FLOOR_MY_ORIG_START..=FLOOR_MY_ORIG_END).contains(&fl) {
            BIRTH_POINTS[BIRTH_TYPE_MY_ORIGINAL]
        } else {
            MKRM_FLOOR_FROM.get(floor_num).map_or(0, |&b| BIRTH_POINTS[b as usize])
        };
        let wl = wall_num as u8;
        base += if (WALL_MY_ORIG_START..=WALL_MY_ORIG_END).contains(&wl) {
            BIRTH_POINTS[BIRTH_TYPE_MY_ORIGINAL]
        } else {
            MKRM_WALL_FROM.get(wall_num).map_or(0, |&b| BIRTH_POINTS[b as usize])
        };
        points += base;
    }

    if mode & EVAL_NECESSITY != 0 {
        let nec = 0x1F; // (1 << (mMkRm_NECESSITY_NUM - 1)) - 1: chair, dresser, wardrobe, table, bed
        let mut total = 0;
        let mut same = false;
        for s in 0..SERIES_NUM {
            if series_type(s) == SERIES_TYPE_BASE {
                total |= search[s];
                if search[s] & nec == nec {
                    points += NECESSITY_SAME_SERIES_BONUS;
                    r.letter_bits |= letter_bit::NECESSITIES_COMPLETE_SAME_SERIES;
                    same = true;
                    break;
                }
            }
        }
        if !same && total & nec == nec {
            points += NECESSITY_DIFF_SERIES_BONUS;
            r.letter_bits |= letter_bit::NECESSITIES_COMPLETE;
        }
    }

    if mode & EVAL_BASE_SERIES != 0 {
        for s in 0..SERIES_NUM {
            if series_type(s) != SERIES_TYPE_BASE || d.series_num_ftr[s] == 0 {
                continue;
            }
            if search[s] & 0x3FF == 0x3FF {
                let wf = series_wf(s);
                points += BASE_SERIES_COMPLETE_FTR_BONUS;
                r.letter_bits |= letter_bit::BASE_SERIES_FTR_COMPLETE;
                if wall_num == wf && floor_num == wf {
                    points += BASE_WALL_AND_FLOOR_BONUS;
                    r.letter_bits |= letter_bit::BASE_SERIES_MATCHING_WALL_AND_FLOOR;
                } else if wall_num == wf {
                    points += BASE_WALL_OR_FLOOR_BONUS;
                    r.base_recommendation = ITM_CARPET_START + wf as u16;
                    r.letter_bits |= letter_bit::BASE_SERIES_WALL_OR_FLOOR_MATCH;
                } else if floor_num == wf {
                    points += BASE_WALL_OR_FLOOR_BONUS;
                    r.base_recommendation = ITM_WALL_START + wf as u16;
                    r.letter_bits |= letter_bit::BASE_SERIES_WALL_OR_FLOOR_MATCH;
                }
                break;
            }
            let n = d.series_num_ftr[s];
            let have = (0..n).filter(|j| (search[s] >> j) & 1 != 0).count() as u32;
            let missing = (0..n).rfind(|j| (search[s] >> j) & 1 == 0).unwrap_or(0);
            if n == have + 1 {
                r.base_recommendation = remain_one_ftr(missing as u16, s);
                r.letter_bits |= letter_bit::BASE_SERIES_FTR_ALMOST_COMPLETE;
                break;
            } else if have >= 6 {
                r.letter_bits |= letter_bit::SERIES_STARTED;
                break;
            }
        }
    }

    let mut completed_theme = None;
    if mode & EVAL_THEME_SERIES != 0 {
        'themes: {
            for s in 0..SERIES_NUM {
                if series_type(s) != SERIES_TYPE_THEME || d.series_num_ftr[s] == 0 {
                    continue;
                }
                let n = d.series_num_ftr[s];
                let wf = series_wf(s);
                if search[s] == perfect(n) {
                    r.series_name = Some(s);
                    if wall_num == wf && floor_num == wf {
                        points += n as i32 * THEME_SERIES_COMPLETE_FTR_BONUS + THEME_WALL_AND_FLOOR_BONUS;
                        completed_theme = Some(s);
                        r.letter_bits |= letter_bit::THEME_SERIES_COMPLETE;
                        break 'themes;
                    }
                    // @BUG: wrong item category for the recommendation.
                    if wall_num == wf && floor_num != wf {
                        r.letter_bits |= letter_bit::SERIES_ALMOST_COMPLETE;
                        r.theme_recommendation = ITM_CARPET_START + floor_num as u16;
                    } else if wall_num != wf && floor_num == wf {
                        r.letter_bits |= letter_bit::SERIES_ALMOST_COMPLETE;
                        r.theme_recommendation = ITM_WALL_START + wall_num as u16;
                    }
                } else {
                    let have = (0..n).filter(|j| (search[s] >> j) & 1 != 0).count() as u32;
                    let missing = (0..n).rfind(|j| (search[s] >> j) & 1 == 0).unwrap_or(0);
                    if n == have + 1 {
                        if wall_num == wf && floor_num == wf {
                            r.theme_recommendation = remain_one_ftr(missing as u16, s);
                            r.letter_bits |= letter_bit::SERIES_ALMOST_COMPLETE;
                        }
                    } else if have >= 6 {
                        r.letter_bits |= letter_bit::SERIES_STARTED;
                    }
                }
            }
            for s in 0..SERIES_NUM {
                if series_type(s) == SERIES_TYPE_THEME
                    && d.series_num_ftr[s] != 0
                    && wall_num == series_wf(s)
                    && floor_num == series_wf(s)
                {
                    points += THEME_WALL_OR_FLOOR_BONUS;
                    r.letter_bits |= letter_bit::THEME_SERIES_WALL_AND_FLOOR_MATCH;
                    break;
                }
            }
        }
    }

    if mode & EVAL_SET_SERIES != 0 {
        for s in 0..SERIES_NUM {
            let n = d.series_num_ftr[s];
            if series_type(s) == SERIES_TYPE_SET && n != 0 && search[s] & perfect(n) == perfect(n) {
                points += n as i32 * SET_SERIES_COMPLETE_BONUS;
                r.letter_bits |= letter_bit::SET_SERIES_COMPLETE;
            }
        }
    }

    if mode & EVAL_LUCKY_FTR != 0 {
        let mut lucky = 0;
        interior(&mut |_, _, _, item| {
            if is_ftr(item) && info(item).is_lucky {
                lucky += 1;
            }
        });
        points += lucky * LUCKY_BONUS;
    }

    if mode & EVAL_DIRECTION != 0 {
        let mut facing = 0;
        interior(&mut |_, x, z, item| {
            if is_ftr(item) && info(item).has_face {
                let dir = (item & 3) as u8;
                if units_of(item, x, z, size_of(item)).iter().any(|&(ux, uz)| check_edge_zone(ux, uz, dir, room_size)) {
                    facing += 1;
                }
            }
        });
        if facing > 0 {
            points -= facing * FACING_WALL_PENALTY;
            r.letter_bits |= letter_bit::BAD_DIRECTION;
        }
    }

    if mode & EVAL_THEME_SERIES != 0 {
        if let Some(theme) = completed_theme {
            let mut obstacles = 0;
            interior(&mut |_, _, _, item| {
                if is_ftr(item) && info(item).series != theme {
                    obstacles += 1;
                }
            });
            if obstacles != 0 {
                points -= obstacles * THEME_OBSTACLE_PENALTY;
                r.letter_bits |= letter_bit::THEME_OBSTACLE;
            }
        }
    }

    if mode & EVAL_LETS_CLEAN != 0 {
        let mut clutter = 0;
        interior(&mut |li, x, z, item| {
            if !is_clutter(item) {
                return;
            }
            if li == 0 {
                clutter += 1;
            } else if !(ITM_DIARY_START..ITM_DIARY_END).contains(&item) {
                let below = ftr_table1[(z as usize) * UT_X_NUM + x as usize];
                if below != EMPTY_NO && is_ftr(below) && info(below).surface_type == SURFACE_TYPE_SURFACE {
                    clutter += 1;
                }
            }
        });
        if clutter != 0 {
            points -= clutter;
            r.letter_bits |= letter_bit::LETS_CLEAN;
        }
    }

    r.points = points.max(0);
    r
}

/// `mMkRm_GetRemainOneFtr`: first furniture of `series` with `group_idx`.
pub fn remain_one_ftr(group_idx: u16, series: usize) -> u16 {
    hra_data()
        .ftr
        .iter()
        .position(|f| f.series == series && f.group_idx == group_idx)
        .map_or(EMPTY_NO, ftr_item_no)
}

/// `mMkRm_DecideLetterNo`: (handbill, present). `random3` is RANDOM(3).
pub fn decide_letter(
    points: i32,
    room_size: usize,
    reward0_given: bool,
    reward1_given: bool,
    letter_bits: u64,
    random3: usize,
) -> (i32, u16) {
    if points >= REWARD0_POINTS && !reward0_given {
        return (HANDBILL_REWARD0, REWARD0_PRESENT);
    }
    if points >= REWARD1_POINTS && !reward1_given {
        return (HANDBILL_REWARD1, REWARD1_PRESENT);
    }
    for i in (0..16).rev() {
        let idx = i + random3 * 16;
        if idx < 64 && (letter_bits >> idx) & 1 != 0 && LETTER_NO_TABLE[idx] != -1 {
            return (LETTER_NO_TABLE[idx], EMPTY_NO);
        }
    }
    let h = if points < 1 {
        0x42
    } else if points < 20000 {
        match room_size {
            0 => 0x43,
            1 => 0x44,
            2 => 0x45,
            _ => 0x220,
        }
    } else if points < REWARD0_POINTS {
        0x46
    } else if points < REWARD1_POINTS {
        0x47
    } else {
        0x48
    };
    (h, EMPTY_NO)
}

/// `mMkRm_CountCharactor` as shipped (both modes scan forward).
pub fn count_character_retail(s: &[u8]) -> usize {
    let len = s.len();
    s.iter().position(|&c| c != b' ').map_or(len, |i| len - i)
}

// ---------------------------------------------------------------------------
// HRA scheduling (m_mark_room.c)
// ---------------------------------------------------------------------------

/// What `mMkRm_MarkRoom` does today.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum HraDaily {
    Nothing,
    /// Send the welcome letter and set `hra_member`.
    Welcome,
    /// Score the house and send the result letter.
    Score,
    /// Send hint letter `HANDBILL_HINT_START + hint`.
    Hint(u32),
}

/// `mMkRm_MarkRoom` decision. `random10` is RANDOM(10);
/// `pick` chooses among `n` free hints (RANDOM(n)).
#[allow(clippy::too_many_arguments)]
pub fn hra_daily(
    is_player: bool,
    on_job: bool,
    member: bool,
    marked_today: bool,
    house_updated: bool,
    random10: i32,
    hint_bits: &mut u32,
    pick: impl FnOnce(u32) -> u32,
) -> HraDaily {
    if !is_player {
        return HraDaily::Nothing;
    }
    if !on_job && !member {
        return HraDaily::Welcome;
    }
    if on_job || marked_today {
        return HraDaily::Nothing;
    }
    if house_updated {
        return HraDaily::Score;
    }
    if random10 != 5 && random10 != 9 {
        return HraDaily::Nothing;
    }
    let all = (1u32 << HINT_NUM) - 1;
    let free = if *hint_bits == all {
        *hint_bits = 0;
        HINT_NUM
    } else {
        (0..HINT_NUM).filter(|i| (*hint_bits >> i) & 1 == 0).count() as u32
    };
    if free == 0 {
        return HraDaily::Nothing;
    }
    let sel = pick(free);
    let hint = (0..HINT_NUM).filter(|i| (*hint_bits >> i) & 1 == 0).nth(sel as usize).unwrap_or(0);
    *hint_bits |= 1 << hint;
    HraDaily::Hint(hint)
}

#[cfg(test)]
mod tests {
    use super::*;

    fn size1(_: u16) -> u8 {
        FTRSIZE_1X1
    }

    #[test]
    fn ftr_index_roundtrip() {
        assert_eq!(ftr_index(0x1000), 0);
        assert_eq!(ftr_index(0x3004), 0x401);
        assert_eq!(ftr_item_no(0x401), 0x3004);
        assert!(is_ftr(0x1234) && is_ftr(0x3000) && !is_ftr(0x2000));
    }

    #[test]
    fn group_indices_and_sizes() {
        let d = hra_data();
        // Every base series: 10 items, necessities 0..=4 then 5..=9.
        for s in 0..SERIES_NUM {
            if MKRM_SERIES_INFO[s].0 == SERIES_TYPE_BASE {
                assert_eq!(d.series_num_ftr[s], 10, "series {s}");
            }
        }
        assert_eq!(d.series_num_ftr[SERIES_OTHER], 913);
    }

    #[test]
    fn feng_shui_lucky_and_cap() {
        assert_eq!(finish_goods_power(41), 20);
        assert_eq!(finish_goods_power(7), 4);
        assert_eq!(finish_goods_power(-3), -1);
        // First furniture (index 0) is orange with a face: north side, facing south.
        let (m, g) = huusui_single(0x1000, 3, 1, 8, FTRSIZE_1X1);
        assert_eq!((m, g), (2, 4));
        // Same piece facing north (rotation 2) against the north wall: penalty.
        let (m, g) = huusui_single(0x1002, 3, 1, 8, FTRSIZE_1X1);
        assert_eq!((m, g), (2 - 10, 4 - 5));
    }

    #[test]
    fn hra_empty_room_and_letters() {
        let empty = [EMPTY_NO; 256];
        let r = mark_room_one_floor([&empty, &empty], 0, 0, 0, FULL_EVALUATION, &size1);
        // Only wallpaper 0 + carpet 0 base points (both group A = 51).
        assert_eq!(r.points, BIRTH_POINTS[MKRM_WALL_FROM[0] as usize] + BIRTH_POINTS[MKRM_FLOOR_FROM[0] as usize]);
        assert_eq!(decide_letter(0, 0, false, false, 0, 0), (0x42, EMPTY_NO));
        assert_eq!(decide_letter(75000, 0, false, false, 0, 0), (HANDBILL_REWARD0, REWARD0_PRESENT));
        assert_eq!(decide_letter(75000, 0, true, false, 0, 0), (0x47, EMPTY_NO));
        assert_eq!(decide_letter(100, 1, true, true, letter_bit::LETS_CLEAN, 1), (61, EMPTY_NO));
        assert_eq!(count_character_retail(b"apple    "), 9);
    }

    #[test]
    fn clutter_counts() {
        let mut floor = [EMPTY_NO; 256];
        floor[16 + 1] = 0x2001; // stationery on the floor
        floor[16 * 2 + 2] = RSV_DOOR;
        let empty = [EMPTY_NO; 256];
        let r = mark_room_one_floor([&floor, &empty], 0, 0, 0, EVAL_LETS_CLEAN, &size1);
        assert_eq!(r.points, 0); // -1 floored
        assert_ne!(r.letter_bits & letter_bit::LETS_CLEAN, 0);
    }

    #[test]
    fn daily_schedule() {
        let mut bits = 0;
        assert_eq!(hra_daily(true, false, false, false, false, 0, &mut bits, |_| 0), HraDaily::Welcome);
        assert_eq!(hra_daily(true, false, true, false, true, 0, &mut bits, |_| 0), HraDaily::Score);
        assert_eq!(hra_daily(true, false, true, false, false, 5, &mut bits, |_| 2), HraDaily::Hint(2));
        assert_eq!(bits, 1 << 2);
        let mut all = (1 << HINT_NUM) - 1;
        assert_eq!(hra_daily(true, false, true, false, false, 9, &mut all, |_| 0), HraDaily::Hint(0));
        assert_eq!(all, 1);
    }
}
